// UC-08: identifica agentes con sistemas operativos sin soporte del fabricante
// Ajusta la lista si agregas otros sistemas al laboratorio.
const EOL = [
  { patron: /windows 7/i, fin: '2020-01-14', nota: 'Windows 7: soporte extendido terminado (ESU hasta ene-2023)' },
  { patron: /windows xp/i, fin: '2014-04-08', nota: 'Windows XP sin soporte' },
  { patron: /windows server 2008/i, fin: '2020-01-14', nota: 'Windows Server 2008/R2 sin soporte' },
  { patron: /windows server 2012/i, fin: '2023-10-10', nota: 'Windows Server 2012/R2 sin soporte' },
  { patron: /centos linux.*\b(6|7)\b/i, fin: '2024-06-30', nota: 'CentOS 6/7 sin soporte' },
  { patron: /red hat.*\b(6|7)\./i, fin: '2024-06-30', nota: 'RHEL 6/7 fuera de mantenimiento' },
  { patron: /ubuntu.*\b(14|16|18)\.04/i, fin: '2023-05-31', nota: 'Ubuntu LTS fuera de soporte estándar' },
];

const agentes = $input.first().json.data?.affected_items ?? [];
const salida = [];

for (const ag of agentes) {
  const so = `${ag.os?.name ?? ''} ${ag.os?.version ?? ''}`.trim();
  const regla = EOL.find((e) => e.patron.test(so));
  if (regla) {
    salida.push({ json: { id: ag.id, nombre: ag.name, ip: ag.ip, so, estado: ag.status, fin_soporte: regla.fin, nota: regla.nota } });
  }
}

// Si no hay equipos obsoletos devolvemos un marcador para informar "todo OK"
return salida.length ? salida : [{ json: { ninguno: true } }];

// Une el inventario de puertos de cada equipo obsoleto y arma el aviso
const RIESGO = { 445: 'SMB', 139: 'NetBIOS', 3389: 'RDP', 135: 'RPC', 23: 'Telnet', 21: 'FTP' };
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const equipos = $('Detectar SO sin soporte').all().map((i) => i.json);
if (equipos[0]?.ninguno) {
  return [{ json: { mensaje: '✅ <b>UC-08 Inventario semanal:</b> no hay agentes con sistemas operativos sin soporte.' } }];
}

const puertos = $input.all().map((i) => i.json);
const bloques = equipos.map((eq, idx) => {
  const items = puertos[idx]?.data?.affected_items ?? [];
  const expuestos = [...new Set(items
    .filter((p) => (p.state ?? 'listening') === 'listening')
    .map((p) => p.local?.port)
    .filter((port) => RIESGO[port]))]
    .map((port) => `${port}/${RIESGO[port]}`);
  return [
    `🖥️ <b>${esc(eq.nombre)}</b> (ID ${esc(eq.id)} · ${esc(eq.ip)}) — ${esc(eq.estado)}`,
    `   SO: ${esc(eq.so)}`,
    `   ${esc(eq.nota)} (desde ${eq.fin_soporte})`,
    `   Servicios de riesgo escuchando: ${expuestos.length ? '<b>' + expuestos.join(', ') + '</b>' : 'ninguno detectado'}`,
  ].join('\n');
});

const mensaje = [
  '🟠 <b>UC-08 · Sistemas sin soporte del fabricante</b>',
  `Equipos detectados: <b>${equipos.length}</b>`,
  '',
  ...bloques,
  '',
  '<b>Acción recomendada:</b> segmentar en VLAN aislada, bloquear SMB/RDP desde otras redes, revisar vulnerabilidades en Dashboard → Vulnerability Detection y planificar la migración.',
].join('\n');

return [{ json: { mensaje } }];
